class EventEmitter {
  constructor() { this.listeners = {}; }
  on(event, fn) {
    (this.listeners[event] = this.listeners[event] || []).push(fn);
  }
  emit(event, data) {
    (this.listeners[event] || []).forEach(fn => fn(data));
  }
}
const emitter = new EventEmitter();
emitter.on('data', (d) => console.log(d));
emitter.emit('data', 'hello');
